style.css:
@-moz-document domain("roblox.com") {
/* Fondo de pantalla con gradiente */
  body {
    background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460, #53354a);
    background-size: cover;
    color: #e1e1e1; /* Texto en gris claro para mayor contraste */
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  }

  /* Contenedores principales con efecto de transparencia */
  .container, .content, .main-content {
    background-color: rgba(34, 34, 59, 0.9); /* Fondo oscuro semi-transparente */
    padding: 15px;
    border-radius: 10px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2); /* Sombra sutil */
  }

  /* Estilo de encabezados */
  h1, h2, h3, h4, h5, h6 {
    color: #f39c12; /* Color ámbar para encabezados */
    font-weight: bold;
  }

  /* Enlaces */
  a {
    color: #3498db; /* Azul para enlaces */
    text-decoration: none;
    font-weight: bold;
  }

  a:hover {
    color: #f39c12; /* Ámbar en hover */
    text-decoration: underline;
  }
  
  /* Botones */
  button, .btn {
    background-color: #e74c3c; /* Rojo para botones */
    color: #f5f5f5;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s ease;
  }

  button:hover, .btn:hover {
    background-color: #c0392b; /* Rojo oscuro al pasar el mouse */
  }
}
